/* Hero background/banner for dashboard */
.dashboard-hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 160px;
  background: linear-gradient(90deg, #38bdf8 0%, #6366f1 100%);
  opacity: 0.18;
  border-radius: 1.2rem 1.2rem 48% 48%/60% 60% 12% 12%;
  z-index: 0;
  pointer-events: none;
}
.dashboard-container {
  position: relative; /* Ensure hero bg is positioned correctly */
  background: var(--card-bg, #fff);
  border-radius: 1.2rem;
  box-shadow: 0 4px 24px 0 rgba(56,189,248,0.10);
  padding: 2rem 1.5rem;
  margin: 2rem auto;
  max-width: 600px;
  transition: background 0.3s;
  opacity: 0;
  transform: translateY(30px);
  animation: dashboardFadeIn 0.8s cubic-bezier(.4,0,.2,1) forwards;
}

@keyframes dashboardFadeIn {
  to {
    opacity: 1;
    transform: none;
  }
}

.dashboard-container h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 1.2rem;
  color: var(--text-main, #23293a);
  letter-spacing: 1px;
  text-shadow: 0 2px 8px rgba(56,189,248,0

.08);
}

.user-info {
  margin-bottom: 2rem;
  color: var(--text-main, #23293a);
  background: linear-gradient(90deg, #e0f2fe 0%, #f0fdfa 100%);
  border-radius: 0.8rem;
  padding: 1rem 1.2rem;
  box-shadow: 0 2px 8px 0 rgba(56,189,248,0.07);
  transition: background 0.3s;
}

.dashboard-cards {
  display: flex;
  gap: 1.2rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.dashboard-card {
  flex: 1 1 120px;
  background: var(--input-bg, #f8fafc);
  border-radius: 0.8rem;
  box-shadow: 0 2px 8px 0 rgba(56,189,248,0.10);
  padding: 1.2rem;
  text-align: center;
  transition: box-shadow 0.3s, background 0.3s, transform 0.3s;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.dashboard-card::before {
  content: "";
