    color: var(--theme-toggle-icon);
    font-size: 1.15rem; 
    box-shadow: 0 2px 8px #2563eb22;
    margin-right: 0.5rem; 

}

.theme-switcher span {
    font-size: 1.08rem;
    font-weight: 600;
    color: var(--theme-toggle-icon);
    letter-spacing: 1px;
    line-height: 2rem;


    transition: color 0.3s;
    margin: 0; 
    padding: 0; 
    display: flex;
    align-items: center;
}




.theme-switcher:focus {
    outline: none;
    box-shadow: 0 0 0 2px #38bdf8aa;
}
